namespace LessonEditor.objects {    public class ComponentOptions {        public static Point Location = IUGlobal.IScene.Size.ToPoint();        public static Size Size = new Size(100, 200);        public static Color BackColor = "#93E6E1".ToColor();        public static Color Forecolor = "#3E5255".ToColor();        public static Color BorderColor = "#009999".ToColor();        public static Font Font = new Font(IUGlobal.Fonts.VIJAJA, 18, FontStyle.Bold);        public static OutlineStyle BorderType = OutlineStyle.Plná;        public string ComponentType = IUGlobal.ComponentKind.SPRITE;        public string ComponentKind = IUGlobal.ComponentKind.SPRITE;        public static int RadiusTL = 0;        public static int RadiusTR = 0;        public static int RadiusBL = 0;        public static int RadiusBR = 0;        public static int PointsCount = 6;        public static int BorderSize = 4;        public static int FrameSize = 0;        public static double InnerCut = 0.5;        public static string Name = "Sprite";        public static string Text = "Text";        public static bool LockedProportions = false;        public static bool IsTransparent = false;        internal static List<string> GetNames() {            return typeof(ComponentOptions).GetFields(BindingFlags.Static | BindingFlags.Public)                .Select(f => f.Name)                .ToList();        }        /// <summary>        /// Get vlas keys and values        /// <br>Example:</br>        /// <br>var data = ShapeDefaults.GetAll();</br>        /// <br>data.ForEach(d => {</br>        /// <br>Console.WriteLine("get data:{0} typeName:{1}", d.Item1, d.Item2.TypeName);</br>        /// <br>});</br>        /// </summary>        public static List<Tuple<string, TypeObject>> GetAll() {            return typeof(ComponentOptions).GetFields(BindingFlags.Static | BindingFlags.Public)             .Select(f =>                 new Tuple<string, TypeObject>(f.Name, new TypeObject(f.GetValue(f)))             )             .ToList<Tuple<string, TypeObject>>();        }    }}